    'Hors de la ville de départ, carburant à votre charge' => ['Outside the pick-up city, fuel is at your expense', 'Fuera de la ciudad de salida, el combustible corre por su cuenta', 'Außerhalb der Abholstadt zahlen Sie den Kraftstoff', '离开取车城市后油费自理', 'خارج مدينة الاستلام، الوقود على حسابك'],
    'Hors de la ville de départ, le carburant est à votre charge' => ['Outside the pick-up city, fuel is at your expense', 'Fuera de la ciudad de salida, el combustible corre por su cuenta', 'Außerhalb der Abholstadt zahlen Sie den Kraftstoff', '离开取车城市后油费自理', 'خارج مدينة الاستلام، يكون الوقود على حسابك'],
    'Hors-piste' => ['Off-road', 'Todoterreno', 'Gelände', '越野', 'الطرق الوعرة'],
    'Hôtel, quartier, repère' => ['Hotel, neighbourhood, landmark', 'Hotel, barrio, punto de referencia', 'Hotel, Viertel, Orientierungspunkt', '酒店、街区、地标', 'فندق، حي، معلم'],
    'Idéal pour' => ['Ideal for', 'Ideal para', 'Ideal für', '适合', 'مثالية لـ'],
    'Il est interdit de fumer à bord. Un forfait de nettoyage peut être facturé.' => ['Smoking on board is not allowed. A cleaning fee may be charged.', 'Está prohibido fumar a bordo. Puede cobrarse una tarifa de limpieza.', 'Rauchen im Fahrzeug ist verboten. Eine Reinigungspauschale kann berechnet werden.', '车内禁止吸烟，否则可能收取清洁费。', 'يُمنع التدخين داخل السيارة. وقد تُفرض رسوم تنظيف.'],
    'Il est libre à partir du {date} à {heure}.' => ['It is free from {date} at {heure}.', 'Está libre a partir del {date} a las {heure}.', 'Es ist ab {date} um {heure} frei.', '{date} {heure}起可租。', 'ستكون متاحة ابتداءً من {date} الساعة {heure}.'],
    'Il vous attend à la sortie avec une pancarte à votre nom (vol {vol})' => ['They will wait for you at the exit with a sign bearing your name (flight {vol})', 'Le esperará a la salida con un cartel con su nombre (vuelo {vol})', 'Er erwartet Sie am Ausgang mit einem Namensschild (Flug {vol})', '司机将在出口举牌等候（航班 {vol}）', 'سينتظرك عند المخرج بلافتة تحمل اسمك (الرحلة {vol})'],
    'Image prestige' => ['Prestige image', 'Imagen de prestigio', 'Repräsentatives Auftreten', '尊贵形象', 'مظهر راقٍ'],
    'Indiquez la date de naissance du conducteur.' => ['Enter the driver’s date of birth.', 'Indique la fecha de nacimiento del conductor.', 'Geben Sie das Geburtsdatum des Fahrers ein.', '请填写驾驶人的出生日期。', 'أدخل تاريخ ميلاد السائق.'],
    'Indiquez la date d’obtention du permis.' => ['Enter the date the licence was issued.', 'Indique la fecha de obtención del permiso.', 'Geben Sie das Ausstellungsdatum des Führerscheins ein.', '请填写驾照取得日期。', 'أدخل تاريخ الحصول على الرخصة.'],
    'Indiquez la destination du voyage.' => ['Enter the trip destination.', 'Indique el destino del viaje.', 'Geben Sie das Reiseziel ein.', '请填写行程目的地。', 'أدخل وجهة الرحلة.'],
    'Indiquez le jour et l’heure de départ.' => ['Enter the pick-up day and time.', 'Indique el día y la hora de salida.', 'Geben Sie Tag und Uhrzeit der Abholung ein.', '请填写取车日期和时间。', 'أدخل يوم ووقت الاستلام.'],
    'Indiquez le jour et l’heure de retour.' => ['Enter the return day and time.', 'Indique el día y la hora de devolución.', 'Geben Sie Tag und Uhrzeit der Rückgabe ein.', '请填写还车日期和时间。', 'أدخل يوم ووقت الإرجاع.'],
    'Indiquez le numéro de vol pour que le chauffeur vous attende.' => ['Enter the flight number so the driver can wait for you.', 'Indique el número de vuelo para que el conductor le espere.', 'Geben Sie die Flugnummer ein, damit der Fahrer auf Sie wartet.', '请填写航班号，以便司机等候。', 'أدخل رقم الرحلة لكي ينتظرك السائق.'],
    'Indiquez l’heure d’atterrissage.' => ['Enter the landing time.', 'Indique la hora de aterrizaje.', 'Geben Sie die Landezeit ein.', '请填写落地时间。', 'أدخل وقت الهبوط.'],
    'Informations' => ['Information', 'Información', 'Informationen', '信息', 'معلومات'],
    'Interdits : sous-location, transport rémunéré de personnes ou de marchandises, courses, remorquage, conduite sous l’effet de l’alcool ou de drogues.' => ['Not allowed: subletting, paid transport of people or goods, racing, towing, driving under the influence of alcohol or drugs.', 'Prohibido: subarrendar, transporte remunerado de personas o mercancías, carreras, remolque, conducir bajo los efectos del alcohol o drogas.', 'Verboten: Untervermietung, bezahlte Personen- oder Güterbeförderung, Rennen, Abschleppen, Fahren unter Alkohol- oder Drogeneinfluss.', '禁止：转租、有偿载客或运货、赛车、拖车、酒后或药后驾驶。', 'يُمنع: التأجير من الباطن، ونقل الأشخاص أو البضائع بأجر، والسباقات، والقطر، والقيادة تحت تأثير الكحول أو المخدرات.'],
    'Intérieur cuir' => ['Leather interior', 'Interior de cuero', 'Lederausstattung', '真皮内饰', 'مقصورة جلدية'],
    'Intérieur silencieux' => ['Quiet interior', 'Interior silencioso', 'Leiser Innenraum', '车内安静', 'مقصورة هادئة'],
    'JETOUR T2 sur une plage' => ['JETOUR T2 on a beach', 'JETOUR T2 en una playa', 'JETOUR T2 an einem Strand', '海滩上的捷途 T2', 'JETOUR T2 على الشاطئ'],
    'JETOUR X50 vu de l’arrière' => ['JETOUR X50 seen from the rear', 'JETOUR X50 visto desde atrás', 'JETOUR X50 von hinten', '捷途 X50 后视图', 'JETOUR X50 من الخلف'],
    'Je ne peux pas répondre à cette demande. L’équipe Yamoo Drive vous répond sur WhatsApp.' => ['I cannot answer this request. The Yamoo Drive team will answer you on WhatsApp.', 'No puedo responder a esta solicitud. El equipo de Yamoo Drive le responde por WhatsApp.', 'Diese Anfrage kann ich nicht beantworten. Das Yamoo Drive Team antwortet Ihnen auf WhatsApp.', '我无法回答这个请求。Yamoo Drive 团队会在 WhatsApp 上回复您。', 'لا يمكنني الرد على هذا الطلب. سيرد عليك فريق Yamoo Drive عبر WhatsApp.'],
    'Je n’ai pas compris. Essayez par exemple « un 7 places sans chauffeur » ou « prix du Prado », ou écrivez à l’équipe sur WhatsApp au {numero}.' => ['I did not understand. Try for example “a 7-seater without a driver” or “Prado price”, or message the team on WhatsApp at {numero}.', 'No he entendido. Pruebe por ejemplo «un 7 plazas sin conductor» o «precio del Prado», o escriba al equipo por WhatsApp al {numero}.', 'Das habe ich nicht verstanden. Versuchen Sie zum Beispiel „ein 7-Sitzer ohne Fahrer“ oder „Preis des Prado“, oder schreiben Sie dem Team auf WhatsApp unter {numero}.', '我没有理解。可以试试“7座自驾”或“普拉多价格”，或通过 WhatsApp {numero} 联系团队。', 'لم أفهم. جرّب مثلًا «سيارة 7 مقاعد بدون سائق» أو «سعر برادو»، أو راسل الفريق عبر WhatsApp على {numero}.'],
    'Je n’ai pas réussi à finir la recherche. Reformulez votre question ou écrivez-nous sur WhatsApp.' => ['I could not finish the search. Rephrase your question or message us on WhatsApp.', 'No he podido terminar la búsqueda. Reformule su pregunta o escríbanos por WhatsApp.', 'Ich konnte die Suche nicht abschließen. Formulieren Sie Ihre Frage neu oder schreiben Sie uns auf WhatsApp.', '搜索未能完成。请换个说法提问，或通过 WhatsApp 联系我们。', 'لم أتمكن من إكمال البحث. أعد صياغة سؤالك أو راسلنا عبر WhatsApp.'],
    'Je regarde…' => ['Checking…', 'Lo estoy mirando…', 'Ich sehe nach…', '正在查询…', 'أتحقق من ذلك…'],
    'Je suis l’assistant automatique du site. Pour parler à l’équipe Yamoo Drive, écrivez sur WhatsApp au {numero}.' => ['I am the website’s automatic assistant. To talk to the Yamoo Drive team, message them on WhatsApp at {numero}.', 'Soy el asistente automático del sitio. Para hablar con el equipo de Yamoo Drive, escriba por WhatsApp al {numero}.', 'Ich bin der automatische Assistent der Website. Um mit dem Yamoo Drive Team zu sprechen, schreiben Sie auf WhatsApp an {numero}.', '我是网站的自动助手。如需联系 Yamoo Drive 团队，请通过 WhatsApp {numero}。', 'أنا المساعد الآلي للموقع. للتحدث مع فريق Yamoo Drive، راسلهم عبر WhatsApp على {numero}.'],
    'Jetour T2 noir garé sur un parking ensoleillé, palmiers et grand arbre en arrière-plan' => ['Black Jetour T2 parked in a sunny car park, palm trees and a large tree in the background', 'Jetour T2 negro aparcado en un aparcamiento soleado, con palmeras y un gran árbol al fondo', 'Schwarzer Jetour T2 auf einem sonnigen Parkplatz, Palmen und ein großer Baum im Hintergrund', '黑色捷途 T2 停在阳光下的停车场，背景是棕榈树和一棵大树', 'Jetour T2 أسود متوقف في موقف مشمس، وخلفه أشجار نخيل وشجرة كبيرة'],
    'Jetour T2, le modèle phare. Photo Husskeyy,' => ['Jetour T2, the flagship model. Photo by Husskeyy,', 'Jetour T2, el modelo estrella. Foto de Husskeyy,', 'Jetour T2, das Spitzenmodell. Foto: Husskeyy,', '捷途 T2，旗舰车型。照片：Husskeyy，', 'Jetour T2، الطراز الأبرز. تصوير Husskeyy،'],
    'Jetour T2, page d’accueil' => ['Jetour T2, home page', 'Jetour T2, página de inicio', 'Jetour T2, Startseite', '捷途 T2，首页', 'Jetour T2، الصفحة الرئيسية'],
    'Journée de 24 heures' => ['24-hour days', 'Jornada de 24 horas', '24-Stunden-Tag', '每天按24小时计', 'يوم من 24 ساعة'],
    'Jusqu’à quinze passagers pour les cortèges, séminaires et sorties de groupe.' => ['Up to fifteen passengers for convoys, seminars and group outings.', 'Hasta quince pasajeros para cortejos, seminarios y salidas en grupo.', 'Bis zu fünfzehn Fahrgäste für Korsos, Seminare und Gruppenausflüge.', '最多可载十五人，适合车队、研讨会和团体出游。', 'حتى خمسة عشر راكبًا للمواكب والندوات والرحلات الجماعية.'],
    'Jusqu’à {heures} heures avant la prise en charge.' => ['Up to {heures} hours before pick-up.', 'Hasta {heures} horas antes de la recogida.', 'Bis {heures} Stunden vor der Abholung.', '取车前{heures}小时内。', 'حتى {heures} ساعة قبل الاستلام.'],
    'Jusqu’à {heures} heures avant le départ' => ['Up to {heures} hours before pick-up', 'Hasta {heures} horas antes de la salida', 'Bis {heures} Stunden vor der Abholung', '取车前{heures}小时内', 'حتى {heures} ساعة قبل الاستلام'],
    'Justificatif de domicile ou de séjour' => ['Proof of address or stay', 'Justificante de domicilio o de estancia', 'Wohnsitz- oder Aufenthaltsnachweis', '住址或居留证明', 'إثبات السكن أو الإقامة'],
    'J’accepte les <a href="{lien}" target="_blank">conditions de location</a> de Yamoo Drive.' => ['I accept the Yamoo Drive <a href="{lien}" target="_blank">rental terms</a>.', 'Acepto las <a href="{lien}" target="_blank">condiciones de alquiler</a> de Yamoo Drive.', 'Ich akzeptiere die <a href="{lien}" target="_blank">Mietbedingungen</a> von Yamoo Drive.', '我接受 Yamoo Drive 的<a href="{lien}" target="_blank">租赁条款</a>。', 'أوافق على <a href="{lien}" target="_blank">شروط الإيجار</a> لدى Yamoo Drive.'],
    'Kribi, Limbé, Dschang…' => ['Kribi, Limbe, Dschang…', 'Kribi, Limbe, Dschang…', 'Kribi, Limbe, Dschang…', '克里比、林贝、德尚…', 'كريبي، ليمبي، دشانغ…'],
    'Kribi, Limbé, Yaoundé, l’Ouest : partez sur la route en SUV récent, avec ou sans chauffeur.' => ['Kribi, Limbe, Yaoundé, the West Region: hit the road in a recent SUV, with or without a driver.', 'Kribi, Limbe, Yaundé, el Oeste: salga a la carretera en un SUV reciente, con o sin conductor.', 'Kribi, Limbe, Yaoundé, der Westen: Fahren Sie im neuen SUV los, mit oder ohne Fahrer.', '克里比、林贝、雅温得、西部大区：开新款 SUV 上路，自驾或带司机。', 'كريبي، ليمبي، ياوندي، المنطقة الغربية: انطلق على الطريق بسيارة SUV حديثة، مع سائق أو بدونه.'],
    'La caution remboursable de {montant}, rendue au retour après l’état des lieux' => ['The refundable deposit of {montant}, returned after the inspection at drop-off', 'El depósito reembolsable de {montant}, devuelto a la vuelta tras la inspección', 'Die rückzahlbare Kaution von {montant}, die nach der Rückgabeprüfung erstattet wird', '可退押金 {montant}，还车验车后退还', 'التأمين المسترد بقيمة {montant}، يُعاد عند الإرجاع بعد فحص السيارة'],
    'La date d’obtention du permis est dans le futur. Vérifiez-la.' => ['The licence issue date is in the future. Check it.', 'La fecha de obtención del permiso está en el futuro. Verifíquela.', 'Das Ausstellungsdatum des Führerscheins liegt in der Zukunft. Bitte prüfen.', '驾照取得日期晚于今天，请核对。', 'تاريخ الحصول على الرخصة في المستقبل. تحقق منه.'],
    'La demande a été refusée ou a expiré sur le téléphone. Réessayez avec le même numéro ou un autre, ou payez à la remise des clés.' => ['The request was declined or expired on the phone. Try again with the same number or another, or pay at key handover.', 'La solicitud fue rechazada o caducó en el teléfono. Inténtelo de nuevo con el mismo número u otro, o pague al entregar las llaves.', 'Die Anfrage wurde auf dem Telefon abgelehnt oder ist abgelaufen. Versuchen Sie es mit derselben oder einer anderen Nummer erneut oder zahlen Sie bei der Schlüsselübergabe.', '手机上的付款请求被拒绝或已过期。请用同一号码或其他号码重试，或在交车时付款。', 'رُفض الطلب أو انتهت صلاحيته على الهاتف. أعد المحاولة بالرقم نفسه أو برقم آخر، أو ادفع عند تسليم المفاتيح.'],
    'La page a expiré. Rechargez-la puis reposez votre question.' => ['The page has expired. Reload it and ask your question again.', 'La página ha caducado. Recárguela y vuelva a hacer su pregunta.', 'Die Seite ist abgelaufen. Laden Sie sie neu und stellen Sie Ihre Frage erneut.', '页面已过期。请刷新后重新提问。', 'انتهت صلاحية الصفحة. أعد تحميلها ثم اطرح سؤالك مجددًا.'],
    'La page est restée ouverte trop longtemps. Rechargez-la puis recommencez.' => ['The page was left open too long. Reload it and start again.', 'La página estuvo abierta demasiado tiempo. Recárguela y vuelva a empezar.', 'Die Seite war zu lange geöffnet. Laden Sie sie neu und beginnen Sie erneut.', '页面打开时间过长。请刷新后重新操作。', 'ظلت الصفحة مفتوحة لمدة طويلة. أعد تحميلها وابدأ من جديد.'],
    'La réponse n’est pas arrivée. Vérifiez votre connexion puis réessayez, ou écrivez-nous sur WhatsApp.' => ['The answer did not arrive. Check your connection and try again, or message us on WhatsApp.', 'La respuesta no ha llegado. Compruebe su conexión y vuelva a intentarlo, o escríbanos por WhatsApp.', 'Die Antwort ist nicht angekommen. Prüfen Sie Ihre Verbindung und versuchen Sie es erneut, oder schreiben Sie uns auf WhatsApp.', '未收到回复。请检查网络后重试，或通过 WhatsApp 联系我们。', 'لم يصل الرد. تحقق من اتصالك وأعد المحاولة، أو راسلنا عبر WhatsApp.'],
    'Langue : {nom}' => ['Language: {nom}', 'Idioma: {nom}', 'Sprache: {nom}', '语言：{nom}', 'اللغة: {nom}'],
    'Le 4x4 le plus demandé à Douala : haut, robuste et spacieux.' => ['The most requested 4x4 in Douala: high, sturdy and spacious.', 'El 4x4 más solicitado en Duala: alto, robusto y espacioso.', 'Der gefragteste Geländewagen in Douala: hoch, robust und geräumig.', '杜阿拉最受欢迎的四驱车：高大、坚固、宽敞。', 'سيارة الدفع الرباعي الأكثر طلبًا في دوالا: عالية ومتينة وواسعة.'],
    'Le SUV compact pour la ville, avec Apple CarPlay et toit ouvrant.' => ['The compact city SUV, with Apple CarPlay and an opening roof.', 'El SUV compacto para la ciudad, con Apple CarPlay y techo practicable.', 'Der kompakte Stadt-SUV mit Apple CarPlay und Schiebedach.', '城市紧凑型 SUV，配 Apple CarPlay 和天窗。', 'سيارة SUV مدمجة للمدينة، مع Apple CarPlay وسقف قابل للفتح.'],
    'Le chauffeur vous attend à la sortie avec une pancarte à votre nom.' => ['The driver waits for you at the exit with a sign bearing your name.', 'El conductor le espera a la salida con un cartel con su nombre.', 'Der Fahrer erwartet Sie am Ausgang mit einem Namensschild.', '司机将在出口举牌等候。', 'ينتظرك السائق عند المخرج بلافتة تحمل اسمك.'],
    'Le chauffeur vous contacte avant l’heure de prise en charge' => ['The driver contacts you before the pick-up time', 'El conductor le contacta antes de la hora de recogida', 'Der Fahrer meldet sich vor der Abholzeit bei Ihnen', '司机会在接载时间前联系您', 'يتصل بك السائق قبل موعد الاستلام'],
    'Le conducteur' => ['The driver', 'El conductor', 'Der Fahrer', '驾驶人', 'السائق'],
    'Le conducteur doit avoir au moins 23 ans le jour du départ.' => ['The driver must be at least 23 on the pick-up day.', 'El conductor debe tener al menos 23 años el día de la salida.', 'Der Fahrer muss am Abholtag mindestens 23 Jahre alt sein.', '取车当天驾驶人须年满23岁。', 'يجب ألا يقل عمر السائق عن 23 عامًا يوم الاستلام.'],
    'Le conducteur doit avoir au moins {age} ans et son permis depuis {permis} ans. Préparez une CNI ou un passeport, le permis de conduire (le permis international est accepté pour les non-résidents) et un justificatif de domicile ou de séjour. Vous envoyez les photos dans le formulaire de réservation.' => ['The driver must be at least {age} and have held a licence for {permis} years. Have a national ID card or passport ready, the driving licence (international licences are accepted for non-residents) and proof of address or stay. You send the photos in the booking form.', 'El conductor debe tener al menos {age} años y el permiso desde hace {permis} años. Prepare un DNI o pasaporte, el permiso de conducir (se acepta el permiso internacional para no residentes) y un justificante de domicilio o de estancia. Usted envía las fotos en el formulario de reserva.', 'Der Fahrer muss mindestens {age} Jahre alt sein und den Führerschein seit {permis} Jahren besitzen. Halten Sie Personalausweis oder Reisepass, den Führerschein (internationaler Führerschein für Nichtansässige akzeptiert) und einen Wohnsitz- oder Aufenthaltsnachweis bereit. Die Fotos senden Sie im Buchungsformular.', '驾驶人须年满{age}岁且驾龄满{permis}年。请准备身份证或护照、驾照（非居民可使用国际驾照）以及住址或居留证明，并在预订表单中上传照片。', 'يجب ألا يقل عمر السائق عن {age} عامًا وأن يحمل الرخصة منذ {permis} أعوام. جهّز بطاقة هوية أو جواز سفر، ورخصة القيادة (تُقبل الرخصة الدولية لغير المقيمين)، وإثبات سكن أو إقامة. ترسل الصور عبر نموذج الحجز.'],
    'Le conducteur doit avoir au moins {age} ans le jour du départ. Choisissez la formule avec chauffeur.' => ['The driver must be at least {age} on the pick-up day. Choose the option with a driver.', 'El conductor debe tener al menos {age} años el día de la salida. Elija la fórmula con conductor.', 'Der Fahrer muss am Abholtag mindestens {age} Jahre alt sein. Wählen Sie die Option mit Fahrer.', '取车当天驾驶人须年满{age}岁。请选择带司机租车。', 'يجب ألا يقل عمر السائق عن {age} عامًا يوم الاستلام. اختر خيار الإيجار مع سائق.'],
    'Le délai de paiement est dépassé et le véhicule a été libéré. Vous pouvez refaire une réservation.' => ['The payment time limit has passed and the vehicle has been released. You can book again.', 'El plazo de pago ha vencido y el vehículo ha quedado libre. Puede volver a reservar.', 'Die Zahlungsfrist ist abgelaufen und das Fahrzeug wurde freigegeben. Sie können erneut buchen.', '付款时限已过，车辆已释放。您可以重新预订。', 'انتهت مهلة الدفع وأصبحت السيارة متاحة. يمكنك الحجز من جديد.'],
    'Le départ doit être au moins {heures} heures après maintenant. Choisissez une heure plus tardive.' => ['Pick-up must be at least {heures} hours from now. Choose a later time.', 'La salida debe ser al menos {heures} horas después de ahora. Elija una hora más tardía.', 'Die Abholung muss mindestens {heures} Stunden in der Zukunft liegen. Wählen Sie eine spätere Uhrzeit.', '取车时间须在{heures}小时之后。请选择更晚的时间。', 'يجب أن يكون الاستلام بعد {heures} ساعات على الأقل من الآن. اختر وقتًا لاحقًا.'],
    'Le jour du départ' => ['On pick-up day', 'El día de la salida', 'Am Abholtag', '取车当天', 'في يوم الاستلام'],
    'Le modèle phare de la flotte : toit panoramique ouvrant et modes tout-terrain.' => ['The flagship of the fleet: opening panoramic roof and off-road modes.', 'El modelo estrella de la flota: techo panorámico practicable y modos todoterreno.', 'Das Spitzenmodell der Flotte: Panorama-Schiebedach und Geländemodi.', '车队旗舰车型：可开启全景天窗和越野模式。', 'الطراز الأبرز في الأسطول: سقف بانورامي قابل للفتح وأوضاع للطرق الوعرة.'],
    'Le paiement de {montant}, en espèces ou par Mobile Money' => ['The payment of {montant}, in cash or by Mobile Money', 'El pago de {montant}, en efectivo o por Mobile Money', 'Die Zahlung von {montant}, bar oder per Mobile Money', '{montant}的付款，现金或 Mobile Money', 'دفع مبلغ {montant}، نقدًا أو عبر Mobile Money'],
    'Le paiement n’a pas abouti' => ['The payment did not go through', 'El pago no se ha completado', 'Die Zahlung ist fehlgeschlagen', '付款未成功', 'لم يكتمل الدفع'],
    'Le paiement n’a pas pu être lancé. Vérifiez le numéro puis réessayez, ou choisissez le paiement à la remise des clés.' => ['The payment could not be started. Check the number and try again, or choose to pay at key handover.', 'No se ha podido iniciar el pago. Compruebe el número y vuelva a intentarlo, o elija pagar al entregar las llaves.', 'Die Zahlung konnte nicht gestartet werden. Prüfen Sie die Nummer und versuchen Sie es erneut oder wählen Sie die Zahlung bei der Schlüsselübergabe.', '无法发起付款。请核对号码后重试，或选择交车时付款。', 'تعذر بدء الدفع. تحقق من الرقم وأعد المحاولة، أو اختر الدفع عند تسليم المفاتيح.'],
    'Le permis doit avoir au moins 2 ans le jour du départ.' => ['The licence must be at least 2 years old on the pick-up day.', 'El permiso debe tener al menos 2 años el día de la salida.', 'Der Führerschein muss am Abholtag mindestens 2 Jahre alt sein.', '取车当天驾龄须满2年。', 'يجب أن يكون عمر الرخصة عامين على الأقل يوم الاستلام.'],
    'Le permis doit avoir au moins {ans} ans le jour du départ. Choisissez la formule avec chauffeur.' => ['The licence must be at least {ans} years old on the pick-up day. Choose the option with a driver.', 'El permiso debe tener al menos {ans} años el día de la salida. Elija la fórmula con conductor.', 'Der Führerschein muss am Abholtag mindestens {ans} Jahre alt sein. Wählen Sie die Option mit Fahrer.', '取车当天驾龄须满{ans}年。请选择带司机租车。', 'يجب أن يكون عمر الرخصة {ans} أعوام على الأقل يوم الاستلام. اختر خيار الإيجار مع سائق.'],
    'Le prix n’a pas pu être calculé. Vérifiez votre connexion puis réessayez.' => ['The price could not be calculated. Check your connection and try again.', 'No se ha podido calcular el precio. Compruebe su conexión y vuelva a intentarlo.', 'Der Preis konnte nicht berechnet werden. Prüfen Sie Ihre Verbindung und versuchen Sie es erneut.', '无法计算价格。请检查网络后重试。', 'تعذر حساب السعر. تحقق من اتصالك وأعد المحاولة.'],
    'Le retour doit être après le départ.' => ['Return must be after pick-up.', 'La devolución debe ser posterior a la salida.', 'Die Rückgabe muss nach der Abholung liegen.', '还车时间须晚于取车时间。', 'يجب أن يكون الإرجاع بعد الاستلام.'],
    'Le siège est à **Douala, Logpom, carrefour Adem**. Nous sommes aussi à Yaoundé et à Bafoussam, et nous livrons aux aéroports de Douala et de Nsimalen. Vous pouvez rendre le véhicule dans une autre ville : des frais de rapatriement s’ajoutent au prix.' => ['Our head office is in **Douala, Logpom, Adem junction**. We are also in Yaoundé and Bafoussam, and we deliver to Douala and Nsimalen airports. You can return the vehicle in another city: a return fee is added to the price.', 'La sede está en **Duala, Logpom, cruce Adem**. También estamos en Yaundé y Bafoussam, y entregamos en los aeropuertos de Duala y Nsimalen. Puede devolver el vehículo en otra ciudad: se suman gastos de repatriación al precio.', 'Unser Hauptsitz ist in **Douala, Logpom, Kreuzung Adem**. Wir sind auch in Yaoundé und Bafoussam und liefern an die Flughäfen Douala und Nsimalen. Sie können das Fahrzeug in einer anderen Stadt zurückgeben: Eine Rückführungsgebühr kommt zum Preis hinzu.', '总部位于**杜阿拉 Logpom 区 Adem 路口**。我们在雅温得和巴富萨姆也设有门店，并可送车至杜阿拉和恩西马伦机场。车辆可在其他城市归还，需加收调车费。', 'يقع المقر الرئيسي في **دوالا، لوغبوم، تقاطع أديم**. ولدينا وكالتان في ياوندي وبافوسام، ونوصل السيارات إلى مطاري دوالا ونسيمالين. يمكنك إعادة السيارة في مدينة أخرى، مع إضافة رسوم الإرجاع إلى السعر.'],
    'Le tout-terrain de luxe, pour sept passagers.' => ['The luxury off-roader, for seven passengers.', 'El todoterreno de lujo, para siete pasajeros.', 'Der Luxus-Geländewagen für sieben Fahrgäste.', '豪华越野车，可载七人。', 'سيارة الطرق الوعرة الفاخرة، لسبعة ركاب.'],
    'Le véhicule est rendu avec le même niveau de carburant qu’au départ. La différence est facturée sinon.' => ['The vehicle is returned with the same fuel level as at pick-up. Otherwise the difference is charged.', 'El vehículo se devuelve con el mismo nivel de combustible que a la salida. Si no, se factura la diferencia.', 'Das Fahrzeug wird mit demselben Tankstand wie bei der Abholung zurückgegeben. Andernfalls wird die Differenz berechnet.', '还车时油量须与取车时一致，否则按差额收费。', 'تُعاد السيارة بمستوى الوقود نفسه عند الاستلام، وإلا يُحتسب الفرق.'],
    'Le véhicule est rendu à l’heure et à l’agence prévues. Une prolongation se demande à l’avance.' => ['The vehicle is returned at the agreed time and branch. Extensions must be requested in advance.', 'El vehículo se devuelve a la hora y en la agencia previstas. Las prórrogas se piden con antelación.', 'Das Fahrzeug wird zur vereinbarten Zeit in der vereinbarten Filiale zurückgegeben. Verlängerungen sind vorab anzufragen.', '车辆须按约定时间在约定门店归还。如需延期，请提前申请。', 'تُعاد السيارة في الموعد وفي الوكالة المتفق عليهما. ويُطلب التمديد مسبقًا.'],
    'Le véhicule vous est réservé. L’équipe confirme sur WhatsApp et vous payez à la remise des clés.' => ['The vehicle is reserved for you. The team confirms on WhatsApp and you pay at key handover.', 'El vehículo queda reservado para usted. El equipo confirma por WhatsApp y usted paga al entregar las llaves.', 'Das Fahrzeug ist für Sie reserviert. Das Team bestätigt auf WhatsApp und Sie zahlen bei der Schlüsselübergabe.', '车辆已为您保留。团队会通过 WhatsApp 确认，交车时付款。', 'السيارة محجوزة لك. يؤكد الفريق عبر WhatsApp وتدفع عند تسليم المفاتيح.'],
    'Le {vehicule} est déjà réservé {quand}.' => ['The {vehicule} is already booked {quand}.', 'El {vehicule} ya está reservado {quand}.', 'Der {vehicule} ist {quand} bereits gebucht.', '{vehicule}{quand}已被预订。', '{vehicule} محجوزة {quand}.'],
    'Le {vehicule} est libre {quand}. Total : **{total}** pour {duree}, {formule}. Touchez le bouton ci-dessous pour finir la réservation.' => ['The {vehicule} is free {quand}. Total: **{total}** for {duree}, {formule}. Tap the button below to finish booking.', 'El {vehicule} está libre {quand}. Total: **{total}** por {duree}, {formule}. Toque el botón de abajo para terminar la reserva.', 'Der {vehicule} ist {quand} frei. Gesamt: **{total}** für {duree}, {formule}. Tippen Sie auf die Schaltfläche unten, um die Buchung abzuschließen.', '{vehicule}{quand}可租。{duree}共 **{total}**，{formule}。点击下方按钮完成预订。', '{vehicule} متاحة {quand}. الإجمالي: **{total}** مقابل {duree}، {formule}. اضغط على الزر أدناه لإتمام الحجز.'],
    'Les amendes et contraventions sont à la charge du client.' => ['Fines and penalties are paid by the customer.', 'Las multas corren a cargo del cliente.', 'Bußgelder trägt der Kunde.', '罚款由客户承担。', 'يتحمل العميل الغرامات والمخالفات.'],
    'Les limites de kilométrage et le prix du kilomètre supplémentaire figurent au contrat.' => ['Mileage limits and the price per extra kilometre are set out in the contract.', 'Los límites de kilometraje y el precio del kilómetro adicional figuran en el contrato.', 'Kilometerbegrenzungen und der Preis pro Zusatzkilometer stehen im Vertrag.', '里程限制及超出里程的单价以合同为准。', 'حدود المسافة وسعر الكيلومتر الإضافي مذكورة في العقد.'],
    'Les photos des modèles viennent de Wikimedia Commons. Elles ont été détourées et leur plaque remplacée par Yamoo Drive ; ces versions modifiées sont diffusées sous la même licence que l’original.' => ['The model photos come from Wikimedia Commons. Yamoo Drive cut them out and replaced their number plates; these edited versions are shared under the same licence as the original.', 'Las fotos de los modelos proceden de Wikimedia Commons. Yamoo Drive las ha recortado y ha sustituido sus matrículas; estas versiones modificadas se difunden con la misma licencia que el original.', 'Die Modellfotos stammen von Wikimedia Commons. Yamoo Drive hat sie freigestellt und die Kennzeichen ersetzt; diese bearbeiteten Fassungen stehen unter derselben Lizenz wie das Original.', '车型照片来自维基共享资源，由 Yamoo Drive 抠图并替换车牌；修改后的版本沿用原图的许可协议。', 'صور الطرازات مأخوذة من Wikimedia Commons. قامت Yamoo Drive بقصّها واستبدال لوحاتها، وتُنشر هذه النسخ المعدّلة بالترخيص نفسه للصور الأصلية.'],
    'Les photos d’intérieur du Jetour T2 et du Jetour X50 sont celles du site yamoodrive.com. La police Figtree est sous licence SIL Open Font License 1.1.' => ['The interior photos of the Jetour T2 and Jetour X50 are from the yamoodrive.com website. The Figtree font is licensed under the SIL Open Font License 1.1.', 'Las fotos de interior del Jetour T2 y del Jetour X50 son las del sitio yamoodrive.com. La fuente Figtree tiene licencia SIL Open Font License 1.1.', 'Die Innenraumfotos des Jetour T2 und des Jetour X50 stammen von yamoodrive.com. Die Schrift Figtree steht unter der SIL Open Font License 1.1.', '捷途 T2 和捷途 X50 的内饰照片来自 yamoodrive.com 网站。Figtree 字体采用 SIL Open Font License 1.1 许可。', 'صور المقصورة الداخلية لـ Jetour T2 وJetour X50 مأخوذة من موقع yamoodrive.com. خط Figtree مرخّص بموجب SIL Open Font License 1.1.'],
    'Les véhicules sont assurés selon la réglementation camerounaise.' => ['Vehicles are insured in line with Cameroonian regulations.', 'Los vehículos están asegurados según la normativa camerunesa.', 'Die Fahrzeuge sind nach kamerunischem Recht versichert.', '车辆按喀麦隆法规投保。', 'السيارات مؤمَّنة وفق اللوائح الكاميرونية.'],
    'Libre à ces dates' => ['Free on these dates', 'Libre en esas fechas', 'Zu diesen Daten frei', '这些日期可租', 'متاحة في هذه التواريخ'],
    'Licence' => ['Licence', 'Licencia', 'Lizenz', '许可', 'الترخيص'],
    'Lien copié' => ['Link copied', 'Enlace copiado', 'Link kopiert', '链接已复制', 'تم نسخ الرابط'],
    'Lire toutes les conditions de location' => ['Read all rental terms', 'Leer todas las condiciones de alquiler', 'Alle Mietbedingungen lesen', '阅读全部租赁条款', 'اقرأ جميع شروط الإيجار'],
    'Livraison à l’aéroport de Yaoundé-Nsimalen' => ['Delivery to Yaoundé-Nsimalen Airport', 'Entrega en el aeropuerto de Yaundé-Nsimalen', 'Lieferung zum Flughafen Yaoundé-Nsimalen', '可送车至雅温得-恩西马伦机场', 'التوصيل إلى مطار ياوندي-نسيمالين'],
    'Livraison à l’aéroport international de Douala' => ['Delivery to Douala International Airport', 'Entrega en el aeropuerto internacional de Duala', 'Lieferung zum internationalen Flughafen Douala', '可送车至杜阿拉国际机场', 'التوصيل إلى مطار دوالا الدولي'],
    'Location de SUV et 4x4 au Cameroun' => ['SUV and 4x4 rental in Cameroon', 'Alquiler de SUV y 4x4 en Camerún', 'SUV- und Geländewagenvermietung in Kamerun', '喀麦隆 SUV 与四驱车租赁', 'تأجير سيارات SUV والدفع الرباعي في الكاميرون'],
    'Location de véhicules avec ou sans chauffeur au Cameroun. Yamoo Drive est la filiale mobilité de Yamoo Group, avec Yamoo Travel et Yamoo Media.' => ['Vehicle rental with or without a driver in Cameroon. Yamoo Drive is the mobility arm of Yamoo Group, alongside Yamoo Travel and Yamoo Media.', 'Alquiler de vehículos con o sin conductor en Camerún. Yamoo Drive es la filial de movilidad de Yamoo Group, junto con Yamoo Travel y Yamoo Media.', 'Fahrzeugvermietung mit oder ohne Fahrer in Kamerun. Yamoo Drive ist die Mobilitätstochter der Yamoo Group, neben Yamoo Travel und Yamoo Media.', '喀麦隆自驾及带司机租车服务。Yamoo Drive 是 Yamoo Group 旗下的出行公司，同属该集团的还有 Yamoo Travel 和 Yamoo Media。', 'تأجير السيارات مع سائق أو بدونه في الكاميرون. Yamoo Drive هي شركة التنقل التابعة لمجموعة Yamoo Group، إلى جانب Yamoo Travel وYamoo Media.'],
    'Location de véhicules avec ou sans chauffeur à Douala, Yaoundé et Bafoussam. Réservation et paiement Mobile Money en ligne.' => ['Vehicle rental with or without a driver in Douala, Yaoundé and Bafoussam. Online booking and Mobile Money payment.', 'Alquiler de vehículos con o sin conductor en Duala, Yaundé y Bafoussam. Reserva y pago Mobile Money en línea.', 'Fahrzeugvermietung mit oder ohne Fahrer in Douala, Yaoundé und Bafoussam. Online-Buchung und Zahlung per Mobile Money.', '杜阿拉、雅温得和巴富萨姆自驾及带司机租车。在线预订，支持 Mobile Money 付款。', 'تأجير السيارات مع سائق أو بدونه في دوالا وياوندي وبافوسام. حجز ودفع عبر Mobile Money على الإنترنت.'],
    'Location terminée' => ['Rental completed', 'Alquiler terminado', 'Miete abgeschlossen', '租赁已结束', 'انتهى الإيجار'],
    'Location {nom}' => ['{nom} rental', 'Alquiler {nom}', 'Miete {nom}', '租用 {nom}', 'إيجار {nom}'],
    'Logpom, carrefour Adem' => ['Logpom, Adem junction', 'Logpom, cruce Adem', 'Logpom, Kreuzung Adem', 'Logpom 区 Adem 路口', 'لوغبوم، تقاطع أديم'],
    'Longues distances' => ['Long distances', 'Largas distancias', 'Lange Strecken', '长途行驶', 'المسافات الطويلة'],
    'Louez un SUV Jetour, un 4x4 ou un van avec ou sans chauffeur à Douala, Yaoundé et Bafoussam. Prix exact en ligne, paiement Mobile Money, livraison aux aéroports.' => ['Rent a Jetour SUV, a 4x4 or a van with or without a driver in Douala, Yaoundé and Bafoussam. Exact price online, Mobile Money payment, airport delivery.', 'Alquile un SUV Jetour, un 4x4 o una furgoneta con o sin conductor en Duala, Yaundé y Bafoussam. Precio exacto en línea, pago Mobile Money, entrega en los aeropuertos.', 'Mieten Sie einen Jetour-SUV, einen Geländewagen oder einen Van mit oder ohne Fahrer in Douala, Yaoundé und Bafoussam. Genauer Preis online, Zahlung per Mobile Money, Lieferung an die Flughäfen.', '在杜阿拉、雅温得和巴富萨姆租用捷途 SUV、四驱车或商务车，可自驾或带司机。在线显示准确价格，支持 Mobile Money 付款，可送车至机场。', 'استأجر سيارة Jetour SUV أو سيارة دفع رباعي أو فانًا، مع سائق أو بدونه، في دوالا وياوندي وبافوسام. سعر دقيق على الإنترنت، ودفع عبر Mobile Money، وتوصيل إلى المطارات.'],
    'Louez un SUV récent, avec ou sans chauffeur' => ['Rent a recent SUV, with or without a driver', 'Alquile un SUV reciente, con o sin conductor', 'Mieten Sie einen neuen SUV, mit oder ohne Fahrer', '租一辆新款 SUV，自驾或带司机', 'استأجر سيارة SUV حديثة، مع سائق أو بدونه'],
    'L’annulation est gratuite jusqu’à **{heures} heures** avant l’heure de prise en charge. Vous pouvez annuler depuis la page de votre réservation.' => ['Cancellation is free up to **{heures} hours** before pick-up time. You can cancel from your booking page.', 'La cancelación es gratuita hasta **{heures} horas** antes de la hora de recogida. Puede cancelar desde la página de su reserva.', 'Die Stornierung ist bis **{heures} Stunden** vor der Abholzeit kostenlos. Sie können auf Ihrer Buchungsseite stornieren.', '取车时间前 **{heures}小时** 内可免费取消，可在预订页面操作。', 'الإلغاء مجاني حتى **{heures} ساعة** قبل موعد الاستلام. يمكنك الإلغاء من صفحة حجزك.'],
    'L’annulation gratuite n’est plus possible pour cette réservation. Écrivez-nous sur WhatsApp.' => ['Free cancellation is no longer possible for this booking. Message us on WhatsApp.', 'La cancelación gratuita ya no es posible para esta reserva. Escríbanos por WhatsApp.', 'Eine kostenlose Stornierung ist für diese Buchung nicht mehr möglich. Schreiben Sie uns auf WhatsApp.', '此预订已无法免费取消。请通过 WhatsApp 联系我们。', 'لم يعد الإلغاء المجاني ممكنًا لهذا الحجز. راسلنا عبر WhatsApp.'],
    'L’équipe a confirmé votre réservation. Vous payez à la remise des clés.' => ['The team has confirmed your booking. You pay at key handover.', 'El equipo ha confirmado su reserva. Usted paga al entregar las llaves.', 'Das Team hat Ihre Buchung bestätigt. Sie zahlen bei der Schlüsselübergabe.', '团队已确认您的预订，交车时付款。', 'أكد الفريق حجزك. تدفع عند تسليم المفاتيح.'],
    'MTN Mobile Money ou Orange Money' => ['MTN Mobile Money or Orange Money', 'MTN Mobile Money u Orange Money', 'MTN Mobile Money oder Orange Money', 'MTN Mobile Money 或 Orange Money', 'MTN Mobile Money أو Orange Money'],
